import java.util.logging.Logger;

public class Account {
    private static final Logger LOG = Logger.getLogger(Account.class.getName());
    private long balanceCents;

    void withdraw(long cents) {
        // Bug was: no check, so balanceCents could go below zero.
        if (cents <= 0 || cents > balanceCents)         // fix: enforce the invariant.
            throw new IllegalArgumentException("invalid withdrawal " + cents);
        balanceCents -= cents;                           // breakpoint here, condition: balanceCents - cents < 0.
        LOG.info(() -> "withdraw ok, remaining=" + balanceCents);   // context, no secrets.
    }

    void deposit(long cents) { balanceCents += cents; }

    public static void main(String[] args) {
        Account a = new Account();
        a.deposit(500);
        a.withdraw(500);                                 // boundary: exactly to zero is fine.
        try { a.withdraw(1); }
        catch (IllegalArgumentException e) { System.out.println(e.getMessage()); }   // invalid withdrawal 1
        System.out.println(a.balanceCents);              // 0
    }
}
